        0,
        0,
        0,
        -1/2*(tauS*uX*(pXY*uX + pYY*uY))/(1 + uX^2 + uY^2),
        0,
        0,
        0,
        0,
        -(pXY*tauS),
        0,
        (tauS*(pEE*(1 + uX^2 + uY^2)^2 + pYY*(1 + uX^2)*(2 + uX^2 + 2*uY^2) - pXY*uX*uY*(3 + 2*uX^2 + 3*uY^2)))/(2*(1 + uY^2)*(1 + uX^2 + uY^2)),
